<template>
   <div class="optimization">
      <OptimizationHeader :title="title" :name="name" :status="status" />

      <div class="option-box">
         <OptimizationReturn title="Лог настройки Регионов и городов">
            <template #option-slot="{ emitEvent }">
               <CustomInput v-model="comandName.value" :placeholder="comandName.name" @update:model-value="emitEvent" />
            </template>
         </OptimizationReturn>
         <div class="optimization-table__box">
            <CustomTable :ItemRows="itemRow" :headerRows="headerRows" :lineClamp="2" height="60px"
               :current-page="pagination.currentPage" :per-page="pagination.perPage" :total="pagination.total"
               @update:currentPage="handlePageChange" @update:perPage="handlePerPageChange" />
         </div>
      </div>
   </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import CustomTable from '@/components/UI/CustomTable';
import OptimizationReturn from '@/components/SEO/OptimizationReturn';
import CustomInput from '@/components/UI/CustomInput';
import { getLocationLogs } from '@/services/apiClient';

const title = ref('Регионы и города');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');

const comandName = ref({
   value: '',
   placeholder: 'поиск по номеру лога',
   name: 'поиск по номеру лога',
   ValidateType: 'empty',
   errorText: '',
});

const itemRow = ref([]);
const headerRows = [
   { name: '#', width: '68px', helper: false },
   { name: 'Дата', helper: false, width: '74px' },
   { name: 'Сотрудники', helper: false, width: '148px' },
   { name: 'Событие', helper: false, width: '282px' },
   { name: 'Ссылка', helper: false, width: '343px' },
];

const pagination = ref({ currentPage: 1, perPage: 20, total: 0 });

const loadLogs = async () => {
   try {
      const logs = await getLocationLogs(pagination.value.perPage, pagination.value.currentPage);
      itemRow.value = logs.data.map(log => ({
         id: { value: log.id, type: 'text', contenteditable: false },
         date: { value: log.date, type: 'text', contenteditable: false },
         employee: { value: log.employee, type: 'text', contenteditable: false },
         multiple: { value: log.event, type: 'text', contenteditable: false },
         noindex: { value: log.link, type: 'link', contenteditable: false },
      }));
      pagination.value.total = logs.total_count || 0;
   } catch (error) {
      console.error('Ошибка при загрузке логов:', error);
   }
};

const handlePageChange = (newPage) => {
   pagination.value.currentPage = newPage;
   loadLogs();
};

const handlePerPageChange = (newPerPage) => {
   pagination.value.perPage = newPerPage;
   pagination.value.currentPage = 1;
   loadLogs();
};

onMounted(() => {
   loadLogs();
});
</script>

